# File: approaches/spg/spg.py
from typing import *

import torch
from torch import Tensor, nn

from utils import assert_type, myprint as print


class SPG(nn.Module):
    def __init__(self, target_module: nn.Module):
        super().__init__()
        assert_type(target_module, nn.Module)
        self.target_module = target_module

        # Stores the maximum absolute standardized gradients per parameter
        self.history_mask = dict()  # type: Dict[int, Dict[str, Tensor]]
        self.dict_amax = {}

        # History for gradients per task and time
        self.dict__idx_task__t__h = {}  # type: Dict[int, Dict[int, Dict[str, Tensor]]]

    def forward(self, x: Tensor) -> Tensor:
        assert_type(x, Tensor)
        out = self.target_module(x)
        return out

    def standardize_pm1(self, x: Tensor) -> Tensor:
        if torch.all(x == 0):
            pass
        else:
            x = self.standardize(x)
        ret = torch.tanh(x)  # scales the standardized value to (-1,1)
        return ret

    @classmethod
    def standardize(cls, x: Tensor) -> Tensor:
        sh = x.shape
        x = x.view(-1)
        ret = (x - x.mean()) / x.std()
        return ret.view(*sh)

    def register_grad(self, idx_task: int, t: int, grads: Dict[str, Tensor]):
        if idx_task not in self.dict__idx_task__t__h.keys():
            self.dict__idx_task__t__h[idx_task] = {}
        if t not in self.dict__idx_task__t__h[idx_task].keys():
            self.dict__idx_task__t__h[idx_task][t] = {}
        for name, grad in grads.items():
            if name in self.dict__idx_task__t__h[idx_task][t].keys():
                grad_prev = self.dict__idx_task__t__h[idx_task][t][name]
            else:
                grad_prev = 0
            grad_new = grad_prev + grad
            self.dict__idx_task__t__h[idx_task][t][name] = grad_new

    def compute_mask(self, idx_task: int):
        if idx_task not in self.dict__idx_task__t__h.keys():
            # might happen in ablation studies
            return
        names = self.dict__idx_task__t__h[idx_task][idx_task].keys()
        history = {}  # type: Dict[str, Tensor]
        for t, dict__name__h in self.dict__idx_task__t__h[idx_task].items():
            assert names == dict__name__h.keys()
            for name, h in dict__name__h.items():
                if name not in history.keys():
                    history[name] = torch.zeros_like(h)
                # Compute a running maximum over the standardized (absolute) gradient value
                history[name] = torch.max(history[name], self.standardize_pm1(h).abs())
        self.history_mask = {idx_task: history.copy()}

        # Clear stored gradients after computing the mask
        self.dict__idx_task__t__h.clear()

    def a_max(self, idx_task: int, latest_module: nn.Module) -> Dict[str, Tensor]:
        if idx_task == 0:
            return None
        else:
            if idx_task not in self.dict_amax.keys():
                ret = dict()
                for name_param, param in latest_module.named_parameters():
                    curr = self.history_mask[idx_task - 1][name_param]
                    if idx_task - 1 in self.dict_amax.keys():
                        prev = self.dict_amax[idx_task - 1][name_param]
                    else:
                        prev = curr
                    v1 = torch.max(prev, curr)
                    ret[name_param] = v1
                self.dict_amax[idx_task] = ret
            return self.dict_amax[idx_task]

    def softmask(self, idx_task: int):
        tgt = self.target_module
        a_max = self.a_max(idx_task, tgt)
        for n, p in tgt.named_parameters():
            if p.grad is None:
                continue
            # Scale gradients based on the importance scores (1 - a_max) per parameter
            red = (1 - a_max[n]).to(p.device)
            p.grad.data *= red

            # Optional printing for debugging dead neurons
            if False:
                num_0 = (red == 0).sum().item()
                num_all = red.numel()
                classname = tgt.__class__.__name__
                msg = f'[{classname}.{n}] dead: {num_0}/{num_all} ({num_0 / num_all:.2%})'
                print(msg)

'''caliban/config/experiment.py

This module defines a set of utility functions to load,
validate, and expand experiment configuration files (typically JSON)
for submitting jobs. The configuration may include compound keys (enclosed
in square brackets, e.g. "[batch_size,learning_rate]") that will be expanded
into a Cartesian product of parameter sets.

The core functions are defined below.
'''

from __future__ import absolute_import, division, print_function

import argparse
import itertools
import re
import sys
from collections import ChainMap
from typing import Any, Dict, List, Optional, Tuple, Union

import commentjson

import caliban.util as u
import caliban.util.argparse as ua
import caliban.util.schema as us

# int, str and bool are allowed in a final experiment; lists are markers for expansion.
ExpValue = Union[int, str, bool]

# Entry in an experiment config. If any values are lists they’re expanded into a sequence of experiment configs.
Expansion = Dict[str, Union[ExpValue, List[ExpValue]]]

# An experiment config can be a single (potentially expandable) dictionary, or a list of many such dicts.
ExpConf = Union[Expansion, List[Expansion]]

# A final experiment can only contain valid ExpValues, no expandable entries.
Experiment = Dict[str, ExpValue]


def _is_compound_key(s: Any) -> bool:
    '''
    Determines if the input s is a compound key defined as a string which uses square brackets
to enclose a comma‐separated list, e.g. "[batch_size,learning_rate]".
    '''
    if (not isinstance(s, str)) or len(s) <= 2:
        return False
    else:
        return s[0] == "[" and s[-1] == "]"


def _tupleize_compound_key(k: str) -> List[str]:
    '''Converts a JSON-input compound key into a tuple of strings.'''
    assert _is_compound_key(k), "{} must be a valid compound key".format(k)
    return tuple([x.strip() for x in k.strip('[]').split(",")])


def _tupleize_compound_value(v: Union[List, bool, str, int, float]) -> Union[List, Tuple]:
    '''
    Converts the value corresponding to a compound key:
      - If v is a list of lists, returns a list of tuples.
      - If v is a list of primitives, returns a tuple of primitives.
      - If v is a single primitive, returns a length‑1 tuple.
    '''
    if isinstance(v, list):
        if isinstance(v[0], list):
            return [tuple(vi) for vi in v]
        else:
            return tuple(v)
    else:
        return (v,)


def _tupleize_compound_item(k: Union[Tuple, str], v: Any) -> Dict:
    '''Converts a JSON-input compound key/value pair into a dictionary with tuple keys and tuple values.'''
    if _is_compound_key(k):
        return {_tupleize_compound_key(k): _tupleize_compound_value(v)}
    else:
        return {k: v}


def tupleize_dict(m: Dict) -> Dict:
    '''Given a dictionary with potential compound keys, converts those keys to tuples
    and their corresponding values to tuples (or list of tuples) as needed.'''
    formatted_items = [_tupleize_compound_item(k, v) for k, v in m.items()]
    return dict(ChainMap(*formatted_items))


def _expand_compound_pair(k: Union[Tuple, str], v: Any) -> Dict:
    '''Given a key-value pair where k is either a single key or a tuple of keys
    and v is the corresponding value or tuple of values, returns a flat dictionary
    mapping individual keys to their values.'''
    if isinstance(k, tuple):
        if not isinstance(v, tuple):
            raise argparse.ArgumentTypeError(
                "function _expand_compound_pair(k, v) requires that if type(k) is tuple, type(v) must also be tuple."
            )
        else:
            return dict(zip(k, v))
    else:
        return {k: v}


def expand_compound_dict(m: Union[Dict, List]) -> Union[Dict, List]:
    '''Given a dictionary (or list of dictionaries) that contains compound keys (tuples),
    returns a dictionary (or list of dictionaries) in which each compound key has been
    expanded into separate key/value pairs.'''
    if isinstance(m, list):
        return [expand_compound_dict(mi) for mi in m]
    else:
        expanded_dicts = [_expand_compound_pair(k, v) for k, v in m.items()]
        return dict(ChainMap(*expanded_dicts))


def expand_experiment_config(items: ExpConf) -> List[Experiment]:
    '''Expand out the experiment config for job submission to Cloud.
    If a dict is provided, it is treated as a single experiment that may have
    expandable (list) entries. If a list is provided, each item is expanded
    and the results are concatenated.
    '''
    if isinstance(items, list):
        return list(itertools.chain.from_iterable([expand_experiment_config(m) for m in items]))

    tupleized_items = tupleize_dict(items)
    return [expand_compound_dict(d) for d in u.dict_product(tupleized_items)]


def validate_compound_keys(m: ExpConf) -> ExpConf:
    '''Check that all keys are strings that obey the compound key formatting rules
    and all values are of allowed types (list, bool, str, int, float).'''

    def check_k(k):
        if not isinstance(k, str):
            raise argparse.ArgumentTypeError("Key '{}' is invalid! Keys must be strings.".format(k))

        valid_re_str = "[^\s\,\]\[]+"
        list_re = re.compile("\A({}|\[\s*({})(\s*,\s*{})*\s*\])\Z".format(valid_re_str, valid_re_str, valid_re_str))

        if list_re.match(k) is None:
            raise argparse.ArgumentTypeError("Key '{}' is invalid! Not a valid compound key.".format(k))

    def check_v(v):
        types = [list, bool, str, int, float]
        if not any(isinstance(v, t) for t in types):
            raise argparse.ArgumentTypeError(
                "Value '{}' in the expanded experiment config '{}' is invalid! Values must be strings, lists, ints, floats or bools.".format(v, m)
            )

    def check_kv_compatibility(k, v):
        # For compound keys, ensure that the number of values matches the number of keys
        if k[0] == "[":
            n_args = len(k.strip('[]').split(","))
            if not isinstance(v, list):
                raise argparse.ArgumentTypeError(
                    "Key '{}' and value '{}' are incompatible: key is compound, but value is not.".format(k, v)
                )
            else:
                if isinstance(v[0], list):
                    for vi in v:
                        if len(vi) != n_args:
                            raise argparse.ArgumentTypeError(
                                "Key '{}' and value '{}' have incompatible arities.".format(k, vi)
                            )
                else:
                    if len(v) != n_args:
                        raise argparse.ArgumentTypeError(
                            "Key '{}' and value '{}' have incompatible arities.".format(k, v)
                        )

    if isinstance(m, list):
        return [validate_compound_keys(i) for i in m]

    for k, v in m.items():
        check_k(k)
        check_v(v)
        check_kv_compatibility(k, v)

    return m


def validate_expansion(m: Expansion) -> Expansion:
    '''Check that all keys are strings and all values are of allowed types without further expansion.'''
    def valid_k(k):
        return isinstance(k, str)
    def valid_v(v):
        types = [list, bool, str, int, float]
        return any(isinstance(v, t) for t in types)
    for k, v in m.items():
        if not valid_k(k):
            raise argparse.ArgumentTypeError("Key '{}' is invalid! Keys must be strings.".format(k))
        if not valid_v(v):
            raise argparse.ArgumentTypeError(
                "Value '{}' in the expanded experiment config '{}' is invalid! Values must be strings, lists, ints, floats or bools.".format(v, m)
            )
    return m


def validate_experiment_config(items: ExpConf) -> ExpConf:
    '''Check that the input is either a valid experiment config (dict or list) that passes
    compound key validation and expansion, or raise an error.
    '''
    if isinstance(items, list) or isinstance(items, dict):
        validate_compound_keys(items)
    else:
        raise argparse.ArgumentTypeError(
            "The experiment config is invalid! The JSON file must contain either a dict or a list."
        )

    for item in expand_experiment_config(items):
        validate_expansion(item)
    return items


def load_experiment_config(s):
    '''Loads and validates an experiment configuration from a file path or from a string.

    If the argument is the string 'stdin', reads from standard input.
    '''
    if isinstance(s, str) and s.lower() == "stdin":
        json_data = commentjson.load(sys.stdin)
    else:
        json_data = ua.argparse_schema(us.Json)(s)

    return validate_experiment_config(json_data)


def experiment_to_args(m: Experiment, base: Optional[List[str]] = None) -> List[str]:
    '''Returns the list of command-line flags corresponding to the supplied experiment
    configuration dictionary. Boolean values are rendered as flag-only (if True).
    '''
    if base is None:
        base = []
    ret = [] + base
    for k, v in m.items():
        opt = "--{}".format(k)
        if isinstance(v, bool):
            if v:
                ret.append(opt)
        else:
            ret.append(opt)
            ret.append(str(v))
    return ret
